// Builds one Slack message from the new ads the actor returned.
// The actor returns an empty list when nothing is new; then we stop here.
const ads = $input.all().map((i) => i.json).filter((a) => a.creativeId);
if (!ads.length) return [];

const cfg = $('Settings').first().json;
const stripQuery = (u) => (u || '').split('?')[0].replace(/^https?:\/\/(www\.)?/, '');
const byQuery = {};
for (const a of ads) (byQuery[a.query] ??= []).push(a);

const lines = [`*${ads.length} new Google ads* from ${Object.keys(byQuery).length} competitor(s), region ${cfg.region}:`];
for (const [q, list] of Object.entries(byQuery)) {
  const formats = {};
  for (const a of list) formats[a.format] = (formats[a.format] || 0) + 1;
  const pages = {};
  for (const a of list) if (a.landingPage) pages[stripQuery(a.landingPage)] = (pages[stripQuery(a.landingPage)] || 0) + 1;
  const topPages = Object.entries(pages).sort((x, y) => y[1] - x[1]).slice(0, 3);
  lines.push('', `*${q}*: ${list.length} new (${Object.entries(formats).map(([f, n]) => `${n} ${f.toLowerCase()}`).join(', ')})`);
  if (topPages.length) lines.push(`Landing pages: ${topPages.map(([p, n]) => `${p} (${n})`).join(', ')}`);
  for (const a of list.sort((x, y) => (y.firstShown || '').localeCompare(x.firstShown || '')).slice(0, 5)) {
    const label = a.headline || `${a.format.toLowerCase()} ad`;
    lines.push(`• <${a.adUrl}|${label.replace(/[<>|]/g, '')}> first shown ${String(a.firstShown).slice(0, 10)}`);
  }
}
return [{ json: { text: lines.join('\n'), adCount: ads.length } }];
